def page(rows, limit, after, team):
    if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= 50:
        raise ValueError("limit must be an integer from 1 to 50")

    def sort_key(row):
        return (-row["score"], row["id"])

    after_key = None if after is None else (-after[0], after[1])
    selected = sorted(
        (
            row for row in rows
            if (team is None or row["team"] == team)
            and (after_key is None or sort_key(row) > after_key)
        ),
        key=sort_key,
    )
    result = selected[:limit]
    next_cursor = None
    if len(selected) > limit:
        last = result[-1]
        next_cursor = [last["score"], last["id"]]

    return {"rows": result, "next": next_cursor}

